    M["discovery: private convoys offered"] = ("discovery", lambda t: sub(t, "where m.player_id = p.id and c.disbanded_at is null and not c.is_private)", "where m.player_id = p.id and c.disbanded_at is null)"))
    M["discovery: nearby list unbounded"] = ("discovery", lambda t: sub(t, "limit least(greatest(coalesce(p_limit, 10), 1), 30)) p;", "limit coalesce(p_limit, 10)) p;"))
    M["discovery: nearby convoy joinable below the rank"] = ("discovery", lambda t: sub(t, "< c.capacity and (select level from profiles where id = v_uid) >= c.min_level)", "< c.capacity)"))
    M["discovery: population invented"] = ("discovery", lambda t: sub(t, "declare v_pop integer := get_online_count();", "declare v_pop integer := 1234;"))
    M["discovery: capacity invented"] = ("discovery", lambda t: sub(t, "'capacity', g.capacity,", "'capacity', coalesce(g.capacity, 500),"))
    M["discovery: region invented"] = ("discovery", lambda t: sub(t, "'region', g.region,", "'region', coalesce(g.region, 'Africa'),"))
    M["discovery: full never reported"] = ("discovery", lambda t: sub(t, "when g.capacity is not null and v_pop >= g.capacity then 'FULL'", "when false then 'FULL'"))
    M["discovery: full at any population"] = ("discovery", lambda t: sub(t, "when g.capacity is not null and v_pop >= g.capacity then 'FULL'", "when g.capacity is null or v_pop >= g.capacity then 'FULL'"))
    M["discovery: maintenance not reported"] = ("discovery", lambda t: sub(t, "case when g.status = 'MAINTENANCE' then 'MAINTENANCE' when", "case when"))
    M["grants: game_servers readable by clients"] = ("discovery", T("grant select on game_servers to authenticated;"))
    M["grants: admin_set_server executable by clients"] = ("discovery", G("admin_set_server", "text, text, integer, text"))
    M["grants: list_nearby_players to anon"] = ("discovery", A("list_nearby_players", "integer"))
    M["grants: list_servers to anon"] = ("discovery", A("list_servers", ""))
    M["spec: start with members offline"] = ("lobby", lambda t: sub(t, "    raise exception 'members_offline';\n  end if;", "    null;\n  end if;"))
    return M
